// Create an OctreePoint container for the given points
XYZ::OctreePointC octree(points);

// Calculate squared distances to avoid sqrt computation
auto squaredDistance = [&searchPoint](const BasicTypesXYZ::Point3D& p) {
    float dx = p.x - searchPoint.x;
    float dy = p.y - searchPoint.y;
    float dz = p.z - searchPoint.z;
    return dx * dx + dy * dy + dz * dz;
};

// Use a max-heap to keep track of k nearest neighbors
std::priority_queue<std::pair<float, size_t>> maxHeap;

// First pass: find initial k candidates
for (size_t i = 0; i < points.size(); ++i) {
    float dist = squaredDistance(points[i]);
    if (maxHeap.size() < k) {
        maxHeap.emplace(dist, i);
    } else if (dist < maxHeap.top().first) {
        maxHeap.pop();
        maxHeap.emplace(dist, i);
    }
}

// If we have fewer points than k, return what we have
if (points.size() <= k) {
    std::vector<size_t> result;
    result.reserve(points.size());
    for (size_t i = 0; i < points.size(); ++i) {
        result.push_back(i);
    }
    return result;
}

// Second pass: use octree for efficient search
std::vector<size_t> nearestNeighbors;
nearestNeighbors.reserve(k);
float maxDistSquared = maxHeap.top().first;

// Get potential candidates from octree
auto candidates = octree.GetCore().GetElementsInSphere(searchPoint, std::sqrt(maxDistSquared));

// Process candidates
for (size_t idx : candidates) {
    float dist = squaredDistance(points[idx]);
    if (dist < maxDistSquared) {
        nearestNeighbors.push_back(idx);
        if (nearestNeighbors.size() >= k) {
            break;
        }
    }
}

// If we didn't find enough neighbors, fall back to brute-force
if (nearestNeighbors.size() < k) {
    nearestNeighbors.clear();
    for (size_t i = 0; i < points.size() && nearestNeighbors.size() < k; ++i) {
        float dist = squaredDistance(points[i]);
        if (dist <= maxDistSquared) {
            nearestNeighbors.push_back(i);
        }
    }
}

// Sort the final results by distance
std::sort(nearestNeighbors.begin(), nearestNeighbors.end(),
    [&](size_t a, size_t b) {
        return squaredDistance(points[a]) < squaredDistance(points[b]);
    });

// Return exactly k neighbors
if (nearestNeighbors.size() > k) {
    nearestNeighbors.resize(k);
}
return nearestNeighbors;

